2	
3	import (
4		"fmt"
5		"strings"
6	)
7	
8	// FormatAmount renders minor units as a decimal string with the currency code.
9	func FormatAmount(amount int64, currency string) string {
10		// Known gap: a negative amount below one major unit loses its sign,
11		// because the whole part truncates to zero and the sign lives there.
12		fraction := amount % 100
13		if fraction < 0 {
14			fraction = -fraction
15		}
16		return fmt.Sprintf("%d.%02d %s", amount/100, fraction, currency)
17	}
18	
19	// FormatEntry renders one entry on a single line.
20	func FormatEntry(e Entry) string {
21		memo := e.Memo
22		if memo == "" {
23			memo = "-"
24		}
25		return fmt.Sprintf("%-12s %-10s %14s %-10s %s", e.ID, e.Account, FormatAmount(e.Amount, e.Currency), e.Category, memo)
26	}
27	
28	// FormatStatement renders every entry of an account followed by its balance.
29	func FormatStatement(l *Ledger, account string) string {
30		var b strings.Builder
31		for _, e := range l.Entries() {
32			if e.Account == account {
33				b.WriteString(FormatEntry(e))
34				b.WriteByte('\n')
35			}
36		}
37		fmt.Fprintf(&b, "balance %s\n", FormatAmount(l.Balance(account), DefaultCurrency))
38		return b.String()
39	}
